    seidel_step(x, y) =
        (A_prev_param(x - 1, y - 1) +
         A_prev_param(x - 1, y) +
         A_prev_param(x - 1, y + 1) +
         A_prev_param(x,     y - 1) +
         A_prev_param(x,     y) +
         A_prev_param(x,     y + 1) +
         A_prev_param(x + 1, y - 1) +
         A_prev_param(x + 1, y) +
         A_prev_param(x + 1, y + 1)) / denom;

    // ------------------------------------------------------------------
    // Schedule for seidel_step:
