    Var i("i"), j("j");
    Func init_A("init_A");

    // A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
    // Map to Halide as A(j, i).
    init_A(j, i) = cast<num_t>(i * (j + 2) + 2) / cast<num_t>(n);

    // Simple CPU schedule for initialization:
    //  - parallelize across rows (i)
    //  - vectorize across columns (j)
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());

    init_A
        .parallel(i)
        .vectorize(j, vec_width);

    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size and time steps
    int n      = N;
    int tsteps = TSTEPS;

    // Buffers for current and next time-step values.
    // We treat dimension 0 as column (j), dimension 1 as row (i),
    // so that C's A[i][j] maps to A(j, i).
    Buffer<num_t, 2> A_cur(n, n);
    Buffer<num_t, 2> A_next(n, n);

    // Initialize A_cur
    init_array(n, A_cur);

    // ImageParam to represent the "previous" time-step array in Halide
    ImageParam A_prev_param(type_of<num_t>(), 2, "A_prev");

    // Vars for spatial indices
    Var x("x"), y("y");

    // One time-step of the 2D Jacobi-like update, expressed in Halide.
    //
    // Original C update (for interior points 1..n-2):
    //
    // A[i][j] = (A[i-1][j-1] + A[i-1][j] + A[i-1][j+1]
    //            + A[i][j-1] + A[i][j] + A[i][j+1]
    //            + A[i+1][j-1] + A[i+1][j] + A[i+1][j+1]) / 9.0;
    //
    // Mapping to Halide coordinates: i -> y, j -> x, A[i][j] -> A_prev_param(x, y).
    //
    // We express the whole domain [0..n-1]x[0..n-1] in one Func and:
    //  - for interior points, apply the 3x3 average
    //  - for boundary points, copy the previous value unchanged
    //
    // This preserves the original semantics (boundaries remain constant)
    // while allowing a single, dense iteration space that is easy to
    // optimize (vectorize, parallelize, tile).
    Func A_prev_clamped("A_prev_clamped");
    Func A_prev_func("A_prev_func");
    Func seidel_step("seidel_step");

    // Wrap the ImageParam in a Func so we can refer to it easily.
    A_prev_func(x, y) = A_prev_param(x, y);

    // Clamp accesses to A_prev to its valid bounds (repeat-edge boundary).
    // This ensures that even when we evaluate expressions like x-1 or x+1
    // at the boundary, we never access out-of-bounds memory.
    Expr x_clamped = clamp(x, 0, A_prev_param.width()  - 1);
    Expr y_clamped = clamp(y, 0, A_prev_param.height() - 1);
    A_prev_clamped(x, y) = A_prev_param(x_clamped, y_clamped);

    // Denominator as the DATA_TYPE (float/double/...)
    Expr denom = cast<num_t>(SCALAR_VAL(9.0));

    // 3x3 stencil sum over A_prev_clamped
    Expr stencil_sum =
        A_prev_clamped(x - 1, y - 1) +
        A_prev_clamped(x - 1, y    ) +
        A_prev_clamped(x - 1, y + 1) +
        A_prev_clamped(x,     y - 1) +
        A_prev_clamped(x,     y    ) +
        A_prev_clamped(x,     y + 1) +
        A_prev_clamped(x + 1, y - 1) +
        A_prev_clamped(x + 1, y    ) +
        A_prev_clamped(x + 1, y + 1);

    // Interior predicate: exactly the region [1..n-2] x [1..n-2].
    // Note that n is a host-side constant; we inject it as an Expr.
    Expr is_interior =
        (x > 0) && (x < (n - 1)) &&
        (y > 0) && (y < (n - 1));

    // For interior: apply stencil; for boundary: copy previous value.
    seidel_step(x, y) =
        select(is_interior, stencil_sum / denom,
               A_prev_func(x, y));

    // ---------------- Scheduling for seidel_step ----------------
    //
    // We have a single-stage stencil Func that reads from A_prev_param
    // and writes a full n x n output. We schedule it to:
    //  - tile the 2D iteration space into 32x32 tiles to improve cache
    //    locality on large grids,
    //  - vectorize across x (fastest-varying dimension),
    //  - parallelize across tiles in the y direction.
    //
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());

    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");

    seidel_step
        // Bound the computational domain to exactly [0..n-1] in each dim.
        .bound(x, 0, n)
        .bound(y, 0, n)
        // Tile into 32x32 blocks for better cache behavior.
        .tile(x, y, xo, yo, xi, yi, 32, 32)
        // Vectorize across x within a tile.
        .vectorize(xi, vec_width)
        // Parallelize across tile rows.
        .parallel(yo);

    // JIT-compile the per-time-step pipeline once, using the chosen target.
    seidel_step.compile_jit(target);

    // Start timing (exclude JIT compilation time).
    auto start = std::chrono::high_resolution_clock::now();

    // Double-buffering over time steps.
    // We keep pointers to the "current" and "next" buffers and swap each step.
    Buffer<num_t, 2> *A_src  = &A_cur;
    Buffer<num_t, 2> *A_dst  = &A_next;

    for (int t = 0; t < tsteps; t++) {
        // Bind the current state as the input image for this step
        A_prev_param.set(*A_src);

        // Compute the full n x n grid for this time step.
        // seidel_step handles both interior updates and boundary copies.
        seidel_step.realize(*A_dst);
        // (We no longer need explicit boundary-copy loops; they are
        // encoded in the Halide pipeline via the select above.)

        // Swap the role of the buffers for the next iteration
        Buffer<num_t, 2> *tmp = A_src;
        A_src = A_dst;
        A_dst = tmp;
    }

    // After the loop, A_src points to the buffer with the final data
    Buffer<num_t, 2> &A_final = *A_src;

    // Stop timing
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result to stderr (similar to the gemm example)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // Recall: A[i][j] in C is A_final(j, i) in Halide.
                std::cerr << A_final(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds with 6 decimal places
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
