    //
    // Original C update (for interior points 1..n-2):
    //
    // A[i][j] = (A[i-1][j-1] + A[i-1][j] + A[i-1][j+1]
    //            + A[i][j-1] + A[i][j] + A[i][j+1]
    //            + A[i+1][j-1] + A[i+1][j] + A[i+1][j+1]) / 9.0;
    //
    // Mapping to Halide coordinates: i -> y, j -> x, A[i][j] -> A_prev_param(x, y).
    Func seidel_step("seidel_step");

    Expr denom = cast<num_t>(SCALAR_VAL(9.0));

    seidel_step(x, y) =
        (A_prev_param(x - 1, y - 1) +
         A_prev_param(x - 1, y) +
         A_prev_param(x - 1, y + 1) +
         A_prev_param(x,     y - 1) +
         A_prev_param(x,     y) +
         A_prev_param(x,     y + 1) +
         A_prev_param(x + 1, y - 1) +
         A_prev_param(x + 1, y) +
         A_prev_param(x + 1, y + 1)) / denom;

    // ------------------------- Schedule for stencil ----------------------
    //
    // We keep the algorithm exactly the same (one Jacobi / Seidel-like
    // step per time iteration, with explicit double-buffering in C++)
    // but aggressively optimize the *schedule* for the 2D stencil:
    //
    //  - Tile the iteration space to improve cache locality.
    //  - Vectorize across the innermost (x) dimension – contiguous in
    //    memory – using a width appropriate for the current CPU target.
    //  - Parallelize across tiles in y (rows of tiles), which exposes
