    //             but small enough to keep good cache behavior.
    //   - tile_y: a modest number of rows per tile to exploit spatial
    //             locality vertically without bloating working sets.
    const int tile_x = vec_width * 8;  // e.g. 8 vectors per tile in X
    const int tile_y = 32;             // 32 rows per tile in Y

    seidel_step
        .tile(x, y, xo, yo, xi, yi, tile_x, tile_y)
        .vectorize(xi, vec_width)
        .parallel(yo);
